//! Public transport seam, isolated because Native has no Ares typed-array API.
//! Failure inventory: global IDs/strides reset at boundaries, angle neighbors
//! disappear, short ranges gain padding, prepared colors drift, or repeated
//! slider/index queries change complete response bytes. Expected full arrays
//! must be captured independently from ca5898aee, never generated by this test.
#[path = "bounded_transfer/input.rs"]
mod input;

use ares_wasm::{SliceOutput, VertexBuffers};
use std::{
    fs,
    path::{Path, PathBuf},
};

fn baseline() -> PathBuf {
    let path = PathBuf::from(
        std::env::var_os("ARES_TRANSFER_BASELINE_DIR")
            .expect("independently captured ca5898aee baseline is required"),
    );
    let provenance: serde_json::Value =
        serde_json::from_slice(&fs::read(path.join("provenance.json")).unwrap()).unwrap();
    assert_eq!(provenance["revision"], "ca5898aee");
    path
}

fn ranges(count: usize) -> impl Iterator<Item = (u32, u32)> {
    (0..count)
        .step_by(1_048_576)
        .map(move |first| (first as u32, (count - first).min(1_048_576) as u32))
}

fn words(path: &Path, values: impl Iterator<Item = u32>) {
    fs::write(path, values.flat_map(u32::to_le_bytes).collect::<Vec<_>>()).unwrap();
}

fn compare(expected: &Path, observed: &Path) {
    let expected = fs::read(expected).unwrap();
    let observed_bytes = fs::read(observed).unwrap();
    assert!(
        expected == observed_bytes,
        "complete bytes differ: {observed:?}; lengths {}/{}; first {:?}",
        expected.len(),
        observed_bytes.len(),
        expected
            .iter()
            .zip(&observed_bytes)
            .position(|(a, b)| a != b)
    );
}

fn check_fields(vertices: &VertexBuffers, expected: &Path, observed: &Path) {
    let count = vertices.count();
    words(
        &observed.join("values.bin"),
        ranges(count)
            .flat_map(|(first, len)| vertices.values_range(first, len).unwrap())
            .map(f32::to_bits),
    );
    words(
        &observed.join("ids.bin"),
        ranges(count).flat_map(|(first, len)| vertices.ids_range(first, len).unwrap()),
    );
    fs::write(
        observed.join("tags.bin"),
        ranges(count)
            .flat_map(|(first, len)| vertices.tags_range(first, len).unwrap())
            .collect::<Vec<_>>(),
    )
    .unwrap();
    fs::write(
        observed.join("options.bin"),
        ranges(count)
            .flat_map(|(first, len)| vertices.options_range(first, len).unwrap())
            .collect::<Vec<_>>(),
    )
    .unwrap();
    for (name, values) in [
        (
            "heights-widths.bin",
            ranges(count)
                .flat_map(|(first, len)| vertices.heights_widths_range(first, len).unwrap())
                .collect::<Vec<_>>(),
        ),
        (
            "positions.bin",
            ranges(count)
                .flat_map(|(first, len)| vertices.segment_positions_range(first, len).unwrap())
                .collect(),
        ),
        (
            "angles.bin",
            ranges(count)
                .flat_map(|(first, len)| vertices.segment_angles_range(first, len).unwrap())
                .collect(),
        ),
    ] {
        words(&observed.join(name), values.into_iter().map(f32::to_bits));
    }
    for name in [
        "values.bin",
        "ids.bin",
        "tags.bin",
        "options.bin",
        "heights-widths.bin",
        "positions.bin",
        "angles.bin",
    ] {
        compare(&expected.join(name), &observed.join(name));
    }
    assert!(vertices.values_range(count as u32, 0).unwrap().is_empty());
    assert!(vertices.ids_range(count as u32, 0).unwrap().is_empty());
    if count > 1_048_577 {
        let values = vertices.values_range(1_048_575, 3).unwrap();
        let expected_values = fs::read(expected.join("values.bin")).unwrap();
        let bytes = values
            .into_iter()
            .flat_map(|value| value.to_bits().to_le_bytes())
            .collect::<Vec<_>>();
        assert_eq!(bytes, expected_values[1_048_575 * 64..1_048_578 * 64]);
        let angles = vertices.segment_angles_range(1_048_575, 3).unwrap();
        let expected_angles = fs::read(expected.join("angles.bin")).unwrap();
        let bytes = angles
            .into_iter()
            .flat_map(|value| value.to_bits().to_le_bytes())
            .collect::<Vec<_>>();
        assert_eq!(bytes, expected_angles[1_048_575 * 4..1_048_578 * 4]);
    }
}

fn check_state(vertices: &mut VertexBuffers, state: usize, expected: &Path, observed: &Path) {
    let (view, roles, options, higher) = input::STATES[state];
    let slider = vertices.moves_slider(0, 2, roles, options);
    assert_eq!(slider.len(), 3, "thumbs and global stop count only");
    words(
        &observed.join("slider.bin"),
        ranges(slider[2] as usize)
            .flat_map(|(first, len)| vertices.slider_gcode_ids_range(first, len).unwrap()),
    );
    let thumbs = vertices.set_moves_higher(higher);
    let range = vertices.set_moves_range().unwrap();
    vertices
        .prepare_vertex_colors(view, roles, options)
        .unwrap();
    let colors = ranges(vertices.count())
        .flat_map(|(first, len)| vertices.vertex_colors_range(first, len).unwrap())
        .collect::<Vec<_>>();
    fs::write(observed.join("colors.bin"), colors).unwrap();
    let counts = vertices.prepare_enabled_indices();
    assert_eq!(counts.len(), 2);
    words(
        &observed.join("segments.bin"),
        ranges(counts[0] as usize)
            .flat_map(|(first, len)| vertices.enabled_segments_range(first, len).unwrap()),
    );
    words(
        &observed.join("enabled-options.bin"),
        ranges(counts[1] as usize)
            .flat_map(|(first, len)| vertices.enabled_options_range(first, len).unwrap()),
    );
    let metadata = serde_json::json!({"range": range, "thumbs": thumbs, "colorRange": serde_json::from_str::<serde_json::Value>(&vertices.color_range(view).unwrap()).unwrap()});
    fs::write(
        observed.join("metadata.json"),
        serde_json::to_vec(&metadata).unwrap(),
    )
    .unwrap();
    for name in [
        "colors.bin",
        "segments.bin",
        "enabled-options.bin",
        "slider.bin",
        "metadata.json",
    ] {
        compare(&expected.join(name), &observed.join(name));
    }
}

fn run(large: bool, repeats: usize) {
    let name = if large { "boundary" } else { "queries" };
    let expected = baseline().join(name);
    let root = std::env::var_os("ARES_TRANSFER_ARTIFACT_DIR")
        .map(PathBuf::from)
        .unwrap_or_else(|| std::env::temp_dir().join("ares-bounded-transfer"));
    let observed = root.join(name);
    fs::create_dir_all(&observed).unwrap();
    let mut output = SliceOutput::from_processed(input::input(large));
    let mut vertices = output.take_vertices();
    drop(output);
    check_fields(&vertices, &expected, &observed);
    for repeat in 0..repeats {
        for state in 0..input::STATES.len() {
            let directory = observed.join(format!("{repeat}-{state}"));
            fs::create_dir_all(&directory).unwrap();
            check_state(
                &mut vertices,
                state,
                &expected.join(format!("state-{state}")),
                &directory,
            );
        }
    }
    fs::write(observed.join("result.json"), serde_json::to_vec(&serde_json::json!({"vertices": vertices.count(), "repeats": repeats, "states": input::STATES.len(), "baseline": "ca5898aee", "allBytesEqual": true})).unwrap()).unwrap();
}

#[test]
#[ignore = "requires independently captured ca5898aee public-API artifacts"]
fn complete_fields_preserve_global_vertices_across_transfer_ranges() {
    run(true, 1);
}

#[test]
#[ignore = "requires independently captured ca5898aee public-API artifacts"]
fn repeated_color_and_slider_queries_preserve_complete_response_bytes() {
    run(false, 8);
}
